import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const Login = () => {
  const [formData, setFormData] = useState({
    identifier: '',  // Matric No or Staff ID
    password: '',
    role: '',
  });
  const [error, setError] = useState('');

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const { identifier, password, role } = formData;

    if (!identifier || !password || !role) {
      setError('Please fill in all fields.');
      return;
    }

    // TODO: Replace with real API call in Step 4
    console.log('Logging in:', formData);
  };

  return (
    <div
      className="d-flex align-items-center justify-content-center"
      style={{ minHeight: '100vh', backgroundColor: 'var(--bg)' }}
    >
      <div className="card-custom" style={{ width: '100%', maxWidth: '420px' }}>

        {/* Header */}
        <div className="text-center mb-4">
          <div style={{ fontSize: '2.5rem' }}>🏥</div>
          <h1 style={{ fontSize: '1.3rem', fontWeight: 700, marginTop: '0.5rem' }}>
            University Health Centre
          </h1>
          <p style={{ color: 'var(--muted)', fontSize: '0.9rem' }}>
            Medication Reminder System
          </p>
        </div>

        <form onSubmit={handleSubmit} noValidate>

          {/* Identifier */}
          <div className="mb-3">
            <label className="form-label fw-semibold">Matric No / Staff ID</label>
            <input
              type="text"
              name="identifier"
              className="form-control"
              placeholder="e.g. RUN/CMP/20/12236 or STF/2024/042"
              value={formData.identifier}
              onChange={handleChange}
            />
          </div>

          {/* Password */}
          <div className="mb-3">
            <label className="form-label fw-semibold">Password</label>
            <input
              type="password"
              name="password"
              className="form-control"
              placeholder="Enter your password"
              value={formData.password}
              onChange={handleChange}
            />
          </div>

          {/* Role */}
          <div className="mb-4">
            <label className="form-label fw-semibold">Login as</label>
            <select
              name="role"
              className="form-select"
              value={formData.role}
              onChange={handleChange}
            >
              <option value="">-- Select your role --</option>
              <option value="patient">Patient</option>
              <option value="doctor">Doctor</option>
              <option value="pharmacist">Pharmacist</option>
              <option value="admin">Admin</option>
            </select>
          </div>

          {/* Error */}
          {error && (
            <div className="alert alert-danger py-2 mb-3" role="alert">
              {error}
            </div>
          )}

          {/* Submit */}
          <button type="submit" className="btn-primary-custom">
            Login
          </button>

          {/* Link to Register */}
          <p className="text-center mt-3 mb-0" style={{ fontSize: '0.9rem', color: 'var(--muted)' }}>
            Don't have an account?{' '}
            <Link to="/register" style={{ color: 'var(--primary)', fontWeight: 600 }}>
              Register here
            </Link>
          </p>

        </form>
      </div>
    </div>
  );
};

export default Login;
